CREATE TEMP TABLE desired_formula_mapping (
  template_code VARCHAR(40) PRIMARY KEY,
  source_sheet VARCHAR(128) NOT NULL,
  option_patch JSONB NOT NULL,
  weight_output_cell VARCHAR(16) NOT NULL,
  area_output_cell VARCHAR(16) NOT NULL
) ON COMMIT DROP;

INSERT INTO desired_formula_mapping VALUES
  ('JS_SINGLE', 'JS', convert_from(decode('', 'hex'), 'UTF8')::jsonb, 'H28', 'N28'),
  ('JS_DOUBLE', 'JS', convert_from(decode('', 'hex'), 'UTF8')::jsonb, 'H28', 'N28'),
  ('JP_SINGLE', 'JP', convert_from(decode('', 'hex'), 'UTF8')::jsonb, 'H29', 'N29'),
  ('JP_DOUBLE', 'JP', convert_from(decode('', 'hex'), 'UTF8')::jsonb, 'H29', 'N29'),
  ('JA_SINGLE', 'JA', convert_from(decode('', 'hex'), 'UTF8')::jsonb, 'H28', 'N28'),
  ('JE_SINGLE', 'JE', convert_from(decode('', 'hex'), 'UTF8')::jsonb, 'H28', 'N28'),
  ('JE_DOUBLE', 'JE', convert_from(decode('', 'hex'), 'UTF8')::jsonb, 'H28', 'N28');

DO $assert$
DECLARE
  missing_templates TEXT;
  missing_mappings TEXT;
BEGIN
  SELECT string_agg(d.template_code, ', ' ORDER BY d.template_code)
    INTO missing_templates
  FROM desired_formula_mapping d
  LEFT JOIN calc.cabinet_template t ON t.template_code = d.template_code
  WHERE t.template_id IS NULL;
  IF missing_templates IS NOT NULL THEN
    RAISE EXCEPTION 'Missing formula templates: %', missing_templates;
  END IF;

  SELECT string_agg(d.template_code, ', ' ORDER BY d.template_code)
    INTO missing_mappings
  FROM desired_formula_mapping d
  LEFT JOIN calc.template_formula_mapping m ON m.template_code = d.template_code
  WHERE m.template_code IS NULL;
  IF missing_mappings IS NOT NULL THEN
    RAISE EXCEPTION 'Missing formula mappings: %', missing_mappings;
  END IF;
END;
$assert$;

UPDATE calc.template_formula_mapping m
SET source_sheet = d.source_sheet,
    option_cells = (COALESCE(m.option_cells, '{}'::jsonb) - 'door' - 'door_or_beam') || d.option_patch,
    weight_output_cell = d.weight_output_cell,
    area_output_cell = d.area_output_cell,
    notes = concat_ws('; ', NULLIF(m.notes, ''), '2026-08-21 unified five-door workbook sync')
FROM desired_formula_mapping d
WHERE m.template_code = d.template_code;

/* Expand short legacy templates by cloning a structurally valid row.  Every
   clone is overwritten from desired_formula_rule below in the same transaction. */
WITH required AS (
  SELECT template_code, count(*) AS required_count
  FROM desired_formula_rule GROUP BY template_code
), available AS (
  SELECT t.template_code, t.template_id, count(r.rule_id) AS available_count
  FROM calc.cabinet_template t
  JOIN desired_formula_mapping d ON d.template_code = t.template_code
  LEFT JOIN calc.cabinet_part_rule r ON r.template_id = t.template_id
  GROUP BY t.template_code, t.template_id
), deficit AS (
  SELECT a.*, r.required_count - a.available_count AS missing_count
  FROM available a JOIN required r USING (template_code)
  WHERE r.required_count > a.available_count
), seed AS (
  SELECT DISTINCT ON (t.template_code) t.template_code, r.*
  FROM calc.cabinet_template t
  JOIN deficit d ON d.template_id = t.template_id
  JOIN calc.cabinet_part_rule r ON r.template_id = t.template_id
  ORDER BY t.template_code, r.sort_no, r.source_row_no, r.rule_id
)
INSERT INTO calc.cabinet_part_rule (
  template_id, part_code, part_name, material_id, condition_formula,
  length_formula, width_formula, thickness_formula, density_formula,
  single_quantity_formula, total_quantity_formula, weight_formula, area_formula,
  surface_treatment, process_route, is_purchasable,
  include_material_cost, include_spray_area, sort_no, source_row_no, raw_rule
)
SELECT s.template_id,
       concat('SYNC_', d.template_code, '_', g.n),
       s.part_name, s.material_id, s.condition_formula,
       s.length_formula, s.width_formula, s.thickness_formula, s.density_formula,
       s.single_quantity_formula, s.total_quantity_formula, s.weight_formula, s.area_formula,
       s.surface_treatment, s.process_route, s.is_purchasable,
       FALSE, FALSE, 20000 + g.n, 20000 + g.n,
       jsonb_build_object('source_row_no', 20000 + g.n, 'values', '[]'::jsonb, 'formulas', '[]'::jsonb)
FROM deficit d
JOIN seed s USING (template_code)
CROSS JOIN LATERAL generate_series(1, d.missing_count) AS g(n);

CREATE TEMP TABLE reusable_formula_rule ON COMMIT DROP AS
SELECT r.rule_id, t.template_code,
       row_number() OVER (
         PARTITION BY t.template_code
         ORDER BY r.sort_no, r.source_row_no, r.rule_id
       ) AS ordinal
FROM calc.cabinet_part_rule r
JOIN calc.cabinet_template t ON t.template_id = r.template_id
JOIN desired_formula_mapping d ON d.template_code = t.template_code;

/* Move source rows out of the final range before re-numbering. */
UPDATE calc.cabinet_part_rule r
SET source_row_no = 10000 + x.ordinal,
    sort_no = 10000 + x.ordinal
FROM reusable_formula_rule x
WHERE x.rule_id = r.rule_id;

UPDATE calc.cabinet_part_rule r
SET source_row_no = d.source_row_no,
    sort_no = d.ordinal,
    raw_rule = d.raw_rule,
    include_material_cost = d.include_material_cost,
    include_spray_area = d.include_spray_area,
    part_name = d.part_name,
    length_formula = d.length_formula,
    width_formula = d.width_formula,
    thickness_formula = d.thickness_formula,
    density_formula = d.density_formula,
    single_quantity_formula = d.single_quantity_formula,
    total_quantity_formula = d.total_quantity_formula,
    weight_formula = d.weight_formula,
    surface_treatment = d.surface_treatment,
    area_formula = d.area_formula
FROM reusable_formula_rule x
JOIN desired_formula_rule d
  ON d.template_code = x.template_code AND d.ordinal = x.ordinal
WHERE r.rule_id = x.rule_id;

DELETE FROM calc.cabinet_part_rule r
USING reusable_formula_rule x
LEFT JOIN desired_formula_rule d
  ON d.template_code = x.template_code AND d.ordinal = x.ordinal
WHERE r.rule_id = x.rule_id AND d.ordinal IS NULL;

DO $verify$
DECLARE
  mismatch TEXT;
BEGIN
  WITH actual AS (
    SELECT t.template_code, count(*) AS row_count,
           min(r.source_row_no) AS first_row, max(r.source_row_no) AS last_row
    FROM calc.cabinet_template t
    JOIN calc.cabinet_part_rule r ON r.template_id = t.template_id
    JOIN desired_formula_mapping d ON d.template_code = t.template_code
    GROUP BY t.template_code
  ), expected AS (
    SELECT template_code, count(*) AS row_count,
           min(source_row_no) AS first_row, max(source_row_no) AS last_row
    FROM desired_formula_rule GROUP BY template_code
  )
  SELECT string_agg(format('%s expected %s rows %s-%s, got %s rows %s-%s',
           e.template_code, e.row_count, e.first_row, e.last_row,
           a.row_count, a.first_row, a.last_row), '; ' ORDER BY e.template_code)
    INTO mismatch
  FROM expected e JOIN actual a USING (template_code)
  WHERE (e.row_count, e.first_row, e.last_row)
     IS DISTINCT FROM (a.row_count, a.first_row, a.last_row);
  IF mismatch IS NOT NULL THEN RAISE EXCEPTION 'Post-migration mismatch: %', mismatch; END IF;
END;
$verify$;

COMMIT;
